<?php
declare(strict_types=1);
require_once __DIR__.'/includes/functions.php';
$error='';
if(post()){
  verifyCsrf();$name=clean('name',150);$email=emailField('email');$subject=clean('subject',190);$message=clean('message',5000);
  if(!$name||!$email||!$subject||mb_strlen($message)<5)$error=setting('contact_validation_error','Please complete all fields with valid information.');
  else{try{db()->prepare('INSERT INTO contact_submissions(name,email,subject,message) VALUES(?,?,?,?)')->execute([$name,$email,$subject,$message]);flash('success',setting('contact_success_message','Your message has been received.'));redirect('contact.php');}catch(Throwable $e){error_log($e->getMessage());$error=setting('contact_failure_message','The message could not be sent right now. Please try again later.');}}
}
$pageTitle='Contact';require __DIR__.'/includes/header.php';
?>
<section class="section"><div class="container"><div class="public-page-heading"><p class="eyebrow"><?=e(setting('contact_eyebrow',"GET IN TOUCH"))?></p><h1 class="section-title"><?=e(setting('contact_title',"Talk to ATACJL."))?></h1><p class="copy"><?=e(setting('contact_intro',"Have a question about a project, event, membership or volunteering? Send us a message and the team will review it."))?></p></div><div class="contact-layout"><div class="contact-form-panel"><h2><?=e(setting('contact_form_title',"Send a message"))?></h2><p class="muted"><?=e(setting('contact_form_hint',"Fields marked as required must be completed."))?></p><?php if($error):?><div class="inline-flash error" role="alert"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="contact-form-grid"><div class="field"><label for="contact-name"><?=e(setting('contact_name_label','Name'))?></label><input id="contact-name" name="name" value="<?=e((string)($_POST['name']??''))?>" autocomplete="name" required></div><div class="field"><label for="contact-email"><?=e(setting('contact_email_label','Email'))?></label><input id="contact-email" type="email" name="email" value="<?=e((string)($_POST['email']??''))?>" autocomplete="email" required></div></div><div class="field"><label for="contact-subject"><?=e(setting('contact_subject_label','Subject'))?></label><input id="contact-subject" name="subject" value="<?=e((string)($_POST['subject']??''))?>" maxlength="190" required></div><div class="field"><label for="contact-message"><?=e(setting('contact_message_label','Message'))?></label><textarea id="contact-message" name="message" minlength="5" maxlength="5000" required><?=e((string)($_POST['message']??''))?></textarea></div><button class="btn primary" type="submit"><?=e(setting('contact_submit_label','Send message'))?> <span aria-hidden="true">→</span></button></form></div><aside class="contact-info-panel"><p class="eyebrow"><?=e(setting('contact_info_eyebrow',"CONTACT DETAILS"))?></p><h2><?=e(setting('contact_info_title',"We're here to help."))?></h2><div class="contact-detail"><span class="contact-detail-icon">⌖</span><div><small><?=e(setting('contact_address_label','Address'))?></small><strong><?=nl2br(e(setting('address','Hammam Sousse, Sousse, Tunisia')))?></strong></div></div><div class="contact-detail"><span class="contact-detail-icon">☎</span><div><small><?=e(setting('contact_phone_label','Phone'))?></small><strong><?=e(setting('phone',''))?></strong></div></div><div class="contact-detail"><span class="contact-detail-icon">✉</span><div><small><?=e(setting('contact_email_info_label','Email'))?></small><strong><a href="mailto:<?=e(setting('email','contact@atacjl.tn'))?>"><?=e(setting('email','contact@atacjl.tn'))?></a></strong></div></div><div class="contact-socials"><?php foreach(['facebook'=>'Facebook','instagram'=>'Instagram','youtube'=>'YouTube'] as $key=>$label):$url=trim(setting('social_'.$key,''));if($url!==''&&filter_var($url,FILTER_VALIDATE_URL)):?><a href="<?=e($url)?>" target="_blank" rel="noopener noreferrer"><?=e($label)?> ↗</a><?php endif;endforeach;?></div></aside></div><?php if(setting('map_embed_url')):?><div class="map-wrap contact-map"><iframe src="<?=e(setting('map_embed_url'))?>" title="Map showing ATACJL location" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div><?php endif;?></div></section>
